contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint256 burnAmount) public payable {
        // Record the total supply and balance of an arbitrary other address before the burn.
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 otherBalanceBefore = c.balanceOf(other); if (__ESBMC_reverted()) return;

        // Attempt the burn as the test contract, which is the owner and the only funded account.
        bool reverted;
        c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The invariant must hold whether the burn succeeded or reverted:
        // totalSupply + balanceOf(other) stays constant when other is not the test contract.
        assert(c.totalSupply() + c.balanceOf(other) == supplyBefore + otherBalanceBefore);
    }

    receive() external payable {}
}

